// Claude's review tests for A38 (Mock selected), A40 (never answers) and A41 (tabs stay built).
// agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

const mk = (id: string, method: Mock['method'], urlPattern: string): Mock => ({
  id, name: id, enabled: true, method, urlPattern, source: 'manual', createdAt: 0,
  response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 },
});

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(mocks: Mock[]): Promise<{ page: Page; panel: Page }> {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks }] };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

test('A38: tick rows, Mock selected makes one mock each, skips what cannot be mocked, with Undo', async () => {
  const { page, panel } = await open([mk('mocked', 'GET', '/api/mocked')]);
  try {
    await page.evaluate(async () => {
      await (await fetch('/api/goals')).text();
      await (await fetch('/api/echo', { method: 'POST', body: '{"a":1}' })).text();
      await (await fetch('/api/mocked')).text();
    });
    const rows = panel.getByTestId('log-row');
    await expect(rows).toHaveCount(3);
    await expect(panel.getByTestId('log-mock-selected')).toHaveCount(0);
    for (const path of ['/api/goals', '/api/echo', '/api/mocked']) {
      await rows.filter({ hasText: path }).getByTestId('log-select').check();
    }
    // Ticking does not open the row.
    await expect(panel.getByTestId('detail-url')).toHaveCount(0);
    const btn = panel.getByTestId('log-mock-selected');
    await expect(btn).toHaveText('Mock selected (3)');
    await btn.click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks.map((m) => `${m.method} ${m.urlPattern}`))
      .toEqual(['GET /api/mocked', 'GET /api/goals', 'POST /api/echo']);
    await expect(panel.getByTestId('undo-bar')).toContainText('2 mocks added (1 skipped)');
    await expect(panel.getByTestId('log-mock-selected')).toHaveCount(0);
    await panel.getByTestId('undo').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks.length).toBe(1);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A38: socket rows have no box', async () => {
  const { page, panel } = await open([]);
  try {
    await page.evaluate(async () => {
      const ws = new WebSocket(`${location.origin.replace('http', 'ws')}/ws/real`);
      await new Promise((r) => (ws.onopen = r));
      await new Promise((r) => setTimeout(r, 150));
      ws.close();
    });
    await expect(panel.getByTestId('log-row').first()).toBeVisible();
    await expect(panel.getByTestId('log-select')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A40: a mock that can never answer is marked, with the reason', async () => {
  const { page, panel } = await open([mk('Catch all', 'ANY', '/api/users/:id'), mk('User 7', 'GET', '/api/users/7'), mk('Other', 'GET', '/api/other')]);
  try {
    await panel.getByTestId('tab-mocks').click();
    const seven = panel.getByTestId('mock-row').filter({ hasText: 'User 7' });
    await expect(seven.getByTestId('mock-unreachable')).toHaveText('Never answers');
    await expect(seven.getByTestId('mock-unreachable')).toHaveAttribute('title', 'Never answers: Catch all above catches all its calls');
    await expect(panel.getByTestId('mock-unreachable')).toHaveCount(1);
    // Moving it above the catch-all clears the mark.
    await seven.getByTestId('mock-up').click();
    await expect(panel.getByTestId('mock-unreachable')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A41: both tabs stay built, so switching keeps what was typed and selected', async () => {
  const { page, panel } = await open([mk('One', 'GET', '/api/one'), mk('Two', 'GET', '/api/two')]);
  try {
    await page.evaluate(async () => { await (await fetch('/api/goals')).text(); });
    await panel.getByTestId('log-filter').fill('goals');
    await panel.getByTestId('log-row').first().click();
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mocks-filter').fill('Two');
    // The Log is still in the page, just hidden.
    await expect(panel.getByTestId('log-filter')).toBeHidden();
    await expect(panel.getByTestId('log-filter')).toHaveCount(1);
    await panel.getByTestId('tab-log').click();
    await expect(panel.getByTestId('log-filter')).toHaveValue('goals');
    await expect(panel.getByTestId('detail-url')).toContainText('/api/goals');
    await expect(panel.getByTestId('mocks-filter')).toBeHidden();
    await panel.getByTestId('tab-mocks').click();
    await expect(panel.getByTestId('mocks-filter')).toHaveValue('Two');
    await expect(panel.getByTestId('mock-row')).toHaveCount(1);
  } finally {
    await panel.close();
    await page.close();
  }
});
